import { ChangeDetectionStrategy, Component, booleanAttribute, input } from '@angular/core';

@Component({
  selector: 'aevko-breadcrumb',
  standalone: true,
  template: '<div role="list"><ng-content /></div>',
  styleUrl: './breadcrumb.component.css',
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: { role: 'navigation', 'data-slot': 'breadcrumb', '[attr.aria-label]': 'label()' },
})
export class AevkoBreadcrumb {
  readonly label = input('Breadcrumb');
}

@Component({
  selector: 'aevko-breadcrumb-item',
  standalone: true,
  template:
    '<div class="item"><ng-content />@if (!current()) { <span class="separator" aria-hidden="true"><span class="fallback">{{ separator() }}</span><ng-content select="[aevkoBreadcrumbSeparator]" /></span> }</div>',
  styleUrl: './breadcrumb-item.component.css',
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: {
    role: 'listitem',
    'data-slot': 'breadcrumb-item',
    '[attr.aria-current]': 'current() ? "page" : null',
  },
})
export class AevkoBreadcrumbItem {
  readonly current = input(false, { transform: booleanAttribute });
  readonly separator = input('/');
}

:host {
  display: block;
}
div {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  list-style: none;
  margin: 0;
  padding: 0;
}

:host {
  display: inline-flex;
}
.item {
  align-items: center;
  color: var(--aevko-muted, #71717a);
  display: inline-flex;
  gap: 0.5rem;
}
:host([aria-current='page']) .item {
  color: var(--aevko-foreground, #09090b);
  font-weight: 500;
}
.separator {
  color: var(--aevko-muted, #71717a);
}
.separator:has(> :not(.fallback)) .fallback {
  display: none;
}
